export function onlyStrings(items: (string | number)[]): string[] {
  const out: string[] = [];
  for (const x of items) {
    // BUG : condition inversée — on garde les nombres au lieu des chaînes
    if (typeof x === 'number') out.push(String(x));
  }
  return out;
}

